-- Study Abroad country content, BATCH 19: Morocco, Tunisia, Ethiopia, Rwanda, Zambia.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('morocco', 'tunisia', 'ethiopia', 'rwanda', 'zambia'));
UPDATE countries SET why_title = 'Why study in Morocco?', why_body = '<p>Morocco offers French, Arabic and English-medium higher education, with modern private institutions such as UM6P and Al Akhawayn University, and strengths in engineering, business and renewable energy.</p><ul><li>Multilingual (Arabic, French, English) education</li><li>UM6P and Al Akhawayn as leading private universities</li><li>Strong in engineering, renewable energy and business</li><li>Gateway between Africa and Europe</li></ul>', visa_title = 'Student visa and residence', visa_body = '<p>Students from visa-required countries apply for a <strong>student visa</strong> at a Moroccan consulate before travel. Visa-exempt students enter and apply for residence locally. After arrival, apply for a residence permit at the local police station.</p><ul><li>Admission letter from a Moroccan institution (the international office at UM6P or AUI assists with visa steps)</li><li>Proof of funds or a scholarship that covers tuition</li><li>Processing reported at 2-8 weeks</li><li>The student residence permit is for study only and does not automatically allow work</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Moroccan consulate and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof (French, Arabic or English)</li><li>Entrance exam or interview for some programmes</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Sources disagree and no UM6P or AUI tuition schedule was found.</p><ul><li>Guide range: public universities about US$2,000-$4,000 a year; private about US$4,000-$8,000 (another guide: US$1,000-$7,000)</li><li>Leading private universities such as AUI and UM6P can be higher; check their schedules</li><li>Living costs: about US$400-$800 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; French or Arabic for local-language programmes</li></ul>' WHERE slug = 'morocco';
UPDATE countries SET why_title = 'Why study in Tunisia?', why_body = '<p>Tunisia offers low-cost degrees in French and Arabic (with some English programmes), strong engineering, medicine and business schools, and close ties with Europe and Africa.</p><ul><li>Low tuition and living costs</li><li>Strong in engineering, medicine and business</li><li>Multilingual (Arabic, French, English)</li><li>Mediterranean location</li></ul>', visa_title = 'Student visa and residence card', visa_body = '<p>A student visa is needed for stays over 90 days, depending on nationality. Nationals of some countries (Maghreb, Ivory Coast, Guinea, Mali, Mauritania, Nigeria, Senegal) need no visa. Students then apply for a <strong>residence card</strong> from the Ministry of the Interior.</p><ul><li>Acceptance letter from a Tunisian institution</li><li>Accommodation evidence and four identity photos for the residence card</li><li>Proof of funds</li><li>International students are not permitted to take paid employment in Tunisia</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Tunisian embassy and Ministry of the Interior site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, and state scholarship applications go through the Ministry of Higher Education.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French or Arabic language proof</li><li>Entrance exam for medicine and engineering</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Sources conflict and official pages do not state current fees.</p><ul><li>Guide ranges: US$500-$4,000 a year, or €1,000-€2,000</li><li>Public universities often run fee-paying programmes for international students; private schools charge more</li><li>Living costs: shared apartments about US$150-$230 a month, studios US$180-$300 (Tunis estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; French or Arabic for local-language programmes</li></ul>' WHERE slug = 'tunisia';
UPDATE countries SET why_title = 'Why study in Ethiopia?', why_body = '<p>Ethiopia is a large African nation with Addis Ababa as the seat of the African Union, and offers low-cost English-medium degrees in medicine, engineering, agriculture and public policy.</p><ul><li>English as the language of instruction</li><li>Addis Ababa University as a leading national university</li><li>Hub of the African Union and international organisations</li><li>Very low costs</li></ul><p>A US State Department advisory in August 2026 advised reconsidering travel to Ethiopia; check your government''s travel advice.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A <strong>student visa</strong> is issued by the Immigration and Citizenship Service (ICS). One guide reports a single-entry 30-day visa at USD 62 (October 2026). Students then need a residence permit.</p><ul><li>Acceptance evidence from the institution</li><li>Proof of tuition payment or scholarship and proof of funds</li><li>Residence permit processing reported at 5-10 business days</li><li>Residence permit fees have changed (previously reported at US$10 a day); a waiver was reported for scholarship students</li><li>Work rights are unclear, so ask ICS before taking a job</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Ethiopian ICS (ics.gov.et) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>AAU uses its own admission portal through the International Students Office.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance requirements per programme</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition figures are inconsistent and no official table for foreign students was found.</p><ul><li>Advanced Nursing MSc at AAU: ETB 1,730 per credit (about ETB 103,800 a year) per an aggregator</li><li>Typical international tuition: US$1,000-$4,000 a year (Scholyhub guide)</li><li>Living costs: about US$250-$500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent where required</li></ul>' WHERE slug = 'ethiopia';
UPDATE countries SET why_title = 'Why study in Rwanda?', why_body = '<p>Rwanda is a safe, fast-developing East African country with English-medium universities, a strong technology and innovation focus and scholarships such as the Mastercard Foundation programme.</p><ul><li>English-medium teaching</li><li>Safe and clean country with strong governance</li><li>Focus on technology, health and agriculture</li><li>Mastercard Foundation Scholars Programme at the University of Rwanda</li></ul>', visa_title = 'Student pass requirements', visa_body = '<p>Rwanda has no separate student visa: you enter on a visitor visa and apply in Rwanda for a <strong>residence permit</strong> through the Irembo portal. The first application should be filed within 15 days of admission.</p><ul><li>Passport valid for at least six months and an admission letter</li><li>Sponsor''s bank statement for the last six months covering tuition, accommodation and living costs</li><li>Pass fee and a recommendation letter addressed to DGIE (can be obtained after arrival)</li><li>Check the current fee and rules on the immigration portal</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Rwanda Directorate General of Immigration and Emigration (Irembo) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university through its application procedure.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Motivation letter for postgraduate programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Only older University of Rwanda fee tables were found.</p><ul><li>UR 2017-18 structure: international students add 20% on top of national and EAC fees</li><li>A 2018-19 table (reported as still valid) lists international Master''s at US$1,915-$4,893 for 24-month programmes plus administrative fees</li><li>An aggregator estimates US$2,500-$4,999 a year for international postgraduates (unsourced)</li><li>Treat all as outdated and confirm with admissions</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'rwanda';
UPDATE countries SET why_title = 'Why study in Zambia?', why_body = '<p>Zambia is a peaceful Southern African country with English-medium universities such as the University of Zambia, offering degrees in medicine, agriculture, engineering and mining.</p><ul><li>English as the language of instruction</li><li>Peaceful, welcoming country</li><li>Strong in mining, agriculture and health</li><li>Close to Victoria Falls and national parks</li></ul>', visa_title = 'Study permit requirements', visa_body = '<p>The <strong>study permit</strong> is for full-time study at a Zambian institution and is applied for through the Zambia Immigration eServices portal. Non-SADC students should get a visa from their home country before travel.</p><ul><li>Online application form, two passport photographs, passport copy and online fee payment</li><li>Permit fees conflict: UNZA lists K6,750 issuance and K9,000 extension on one page (older: K750), University of Lusaka and Cavendish cite about K9,000 and K9,090</li><li>SADC students apply once registered and physically in Zambia</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Zambia Department of Immigration and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance requirements per programme</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fee schedules conflict and none is dated 2026.</p><ul><li>UNZA undergraduate (older schedule): about K51,363 (arts), K62,890 (science) and K77,943 (medicine) a year for international students, paid in four instalments</li><li>Another UNZA page lists K15,723 a year for a science programme</li><li>Living costs: about US$250-$500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English is the medium of instruction; proof where required</li></ul>' WHERE slug = 'zambia';
COMMIT;
